function buildSuggester(entries, k) {
  const newNode = () => ({ children: new Map(), top: [] });
  const root = newNode();
  const offer = (node, q, c) => {
    node.top.push({ q, c });
    node.top.sort((a, b) => b.c - a.c || a.q.localeCompare(b.q));
    if (node.top.length > k) node.top.pop();
  };
  for (const [q, c] of entries) {
    let node = root;
    offer(node, q, c);
    for (const ch of q) {
      if (!node.children.has(ch)) node.children.set(ch, newNode());
      node = node.children.get(ch);
      offer(node, q, c);
    }
  }
  return function suggest(prefix) {
    let node = root;
    for (const ch of prefix) {
      node = node.children.get(ch);
      if (!node) return [];
    }
    return node.top.map((t) => t.q);
  };
}
